CREATE TABLE notification_reads (org_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,item_key CHAR(64) NOT NULL,read_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(org_id,user_id,item_key),FOREIGN KEY(org_id) REFERENCES organizations(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE announcements (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,author_id CHAR(36) NOT NULL,title VARCHAR(160) NOT NULL,body TEXT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),withdrawn BOOLEAN NOT NULL DEFAULT FALSE,INDEX(org_id,created_at),FOREIGN KEY(org_id) REFERENCES organizations(id) ON DELETE CASCADE,FOREIGN KEY(author_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE announcement_batches (announcement_id CHAR(36) NOT NULL,batch_id CHAR(36) NOT NULL,PRIMARY KEY(announcement_id,batch_id),FOREIGN KEY(announcement_id) REFERENCES announcements(id) ON DELETE CASCADE,FOREIGN KEY(batch_id) REFERENCES batches(id) ON DELETE CASCADE) ENGINE=InnoDB;
